// semrs.com agency pages (block markup) for test.semrs.com.
// Run: node content-src/agency/build-agency.mjs
// Output: pages/agency/<slug>.html + pages/agency/manifest.json (title, parent, SEO, ads/index flags).
// Copy follows BRAND.md: plain words, no guarantees, no invented numbers, no testimonials.
// [SET …] marks values only the owner can fill in (prices, founder, address).
import fs from 'fs';
import path from 'path';

const OUT = 'pages/agency';
const EMAIL = 'admin@semrs.com';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const json = (o) => JSON.stringify(o).replace(/--/g, '\\u002d\\u002d');

// ---------- Section helpers ----------
const p = (t, cls) => `<!-- wp:paragraph${cls ? ' ' + json({ className: cls }) : ''} -->\n<p${cls ? ` class="${cls}"` : ''}>${t}</p>\n<!-- /wp:paragraph -->`;
const h = (t, level = 2, center = false) => {
	const a = {};
	if (level !== 2) a.level = level;
	if (center) a.textAlign = 'center';
	return `<!-- wp:heading${Object.keys(a).length ? ' ' + json(a) : ''} -->\n<h${level} class="wp-block-heading${center ? ' has-text-align-center' : ''}">${esc(t)}</h${level}>\n<!-- /wp:heading -->`;
};
const buttons = (items, center = false) => `<!-- wp:buttons${center ? ' {"layout":{"type":"flex","justifyContent":"center"}}' : ''} -->\n<div class="wp-block-buttons">${items.map(([t, u, outline]) => `<!-- wp:button${outline ? ' {"className":"is-style-outline"}' : ''} -->\n<div class="wp-block-button${outline ? ' is-style-outline' : ''}"><a class="wp-block-button__link wp-element-button" href="${u}">${esc(t)}</a></div>\n<!-- /wp:button -->`).join('\n\n')}</div>\n<!-- /wp:buttons -->`;
const section = (attrs, inner) => `<!-- wp:semrs/container ${json({ align: 'full', tag: 'section', padTop: 72, padBottom: 72, ...attrs })} -->\n${inner.filter(Boolean).join('\n\n')}\n<!-- /wp:semrs/container -->`;
const grid = (cols, inner, gap = 24) => `<!-- wp:semrs/container ${json({ layout: 'grid', columns: cols, columnsTablet: Math.min(cols, 2), width: 'full', gap })} -->\n${inner.join('\n\n')}\n<!-- /wp:semrs/container -->`;
const card = (icon, title, text, link, url) => `<!-- wp:semrs/service-card ${json({ icon, title, text, ...(link ? { link, url } : {}) })} /-->`;
const checks = (items, cols = 1) => `<!-- wp:semrs/icon-list ${json({ items: items.join('\n'), icon: 'check-circle', size: 20, ...(cols > 1 ? { columns: cols } : {}) })} /-->`;
const group = (inner) => `<!-- wp:group {"layout":{"type":"default"}} -->\n<div class="wp-block-group">${inner.join('\n\n')}</div>\n<!-- /wp:group -->`;
const faq = (items, title = 'Frequently asked questions') => section({ width: 'narrow' }, [p('Questions', 'semrs-eyebrow'), h(title), `<!-- wp:semrs/accordion -->\n${items.map(([q, a], i) => `<!-- wp:semrs/accordion-item ${json({ title: q, ...(i === 0 ? { open: true } : {}) })} -->\n${p(esc(a))}\n<!-- /wp:semrs/accordion-item -->`).join('\n\n')}\n<!-- /wp:semrs/accordion -->`]);
const steps = (title, items, eyebrow = 'How it works') => section({}, [p(eyebrow, 'semrs-eyebrow'), h(title), grid(items.length > 3 ? 4 : 3, items.map(([icon, t, x]) => group([`<!-- wp:semrs/icon ${json({ icon, size: 44, shape: 'circle', bg: '#fbf4e0' })} /-->`, h(t, 3), p(esc(x))])), 32)]);
const cta = (title, text, btn = ['Get a free SEO review', '/get-a-quote/']) => section({ gradient: 'navy', textColor: '#ffffff', padTop: 64, padBottom: 64 }, [h(title, 2, true), `<!-- wp:paragraph {"align":"center"} -->\n<p class="has-text-align-center">${esc(text)}</p>\n<!-- /wp:paragraph -->`, buttons([btn], true)]);
const hero = (eyebrow, title, lead, btns, points) => section({ className: 'semrs-hero-cover', padTop: 80, padBottom: 64 }, [p(esc(eyebrow), 'semrs-eyebrow'), h(title, 1), p(esc(lead), 'semrs-lead'), buttons(btns), points ? checks(points, 2) : '']);
const tools = (list) => section({ bg: 'var(--sp-surface)', padTop: 56, padBottom: 56 }, [p('Try it yourself first', 'semrs-eyebrow'), h('Free tools for this service'), p('No signup. Use them to check your own site before you talk to us.'), grid(3, list.map(([icon, t, x, slug]) => card(icon, t, x, 'Open the tool', `/tools/${slug}/`)))]);
const form = (o) => `<!-- wp:semrs/contact-form ${json({ recipient: EMAIL, defaultCountry: 'US', showPhone: true, showWhatsapp: true, redirect: '/thank-you/', consent: 'I agree that SEMRS may contact me about my request. See the privacy policy.', ...o })} /-->`;

// ---------- Rich sections (Pro blocks, light: no images, inline SVG only) ----------
const anim = (s, a = 'fade-up') => s.replace(/^<!-- wp:semrs\/container \{/, `<!-- wp:semrs/container {"semrsAnimation":"${a}",`);
const fancy = (before, words, after = '', level = 1) => `<!-- wp:semrs/fancy-heading ${json({ before, fancy: words.join('\n'), after, style: 'typing', level: 'h' + level })} /-->`;
const counter = (number, label, icon, suffix = '', prefix = '') => `<!-- wp:semrs/counter ${json({ number, label, icon, suffix, prefix })} /-->`;
const table = (head, rows, caption) => `<!-- wp:table {"className":"is-style-stripes semrs-compare"} -->\n<figure class="wp-block-table is-style-stripes semrs-compare"><table><thead><tr>${head.map((c) => `<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>${caption ? `<figcaption class="wp-element-caption">${esc(caption)}</figcaption>` : ''}</figure>\n<!-- /wp:table -->`;
const tabs = (items) => `<!-- wp:semrs/tabs {"style":"pills"} -->\n${items.map(([title, icon, inner]) => `<!-- wp:semrs/tab ${json({ title, icon })} -->\n${inner.join('\n\n')}\n<!-- /wp:semrs/tab -->`).join('\n\n')}\n<!-- /wp:semrs/tabs -->`;
const html = (markup) => `<!-- wp:html -->\n${markup}\n<!-- /wp:html -->`;
// Typical SEO journey: an illustration (labelled), not a result. Colours follow the theme (dark mode safe).
const seoChart = () => html(`<figure class="semrs-chart" role="img" aria-label="Illustration of a typical SEO journey over 12 months: technical fixes first, then content, then authority, with organic visibility rising gradually.">
<svg viewBox="0 0 640 300" width="100%" height="auto" xmlns="http://www.w3.org/2000/svg">
<defs><linearGradient id="semrs-g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--sp-accent,#d4a72c)" stop-opacity=".45"/><stop offset="1" stop-color="var(--sp-accent,#d4a72c)" stop-opacity="0"/></linearGradient></defs>
<g stroke="currentColor" stroke-opacity=".12">${[60, 110, 160, 210, 260].map((y) => `<line x1="40" y1="${y}" x2="620" y2="${y}"/>`).join('')}</g>
<rect x="40" y="20" width="150" height="240" fill="currentColor" fill-opacity=".04"/><rect x="190" y="20" width="230" height="240" fill="currentColor" fill-opacity=".07"/><rect x="420" y="20" width="200" height="240" fill="currentColor" fill-opacity=".1"/>
<text x="115" y="40" text-anchor="middle" font-size="13" font-weight="700" fill="currentColor">Months 1–3 · Fix</text><text x="305" y="40" text-anchor="middle" font-size="13" font-weight="700" fill="currentColor">Months 3–6 · Content</text><text x="520" y="40" text-anchor="middle" font-size="13" font-weight="700" fill="currentColor">Months 6–12 · Authority</text>
<path d="M40 250 C120 248 160 240 200 226 S300 190 360 160 S470 104 620 70 L620 260 L40 260 Z" fill="url(#semrs-g)"/>
<path class="semrs-chart__line" d="M40 250 C120 248 160 240 200 226 S300 190 360 160 S470 104 620 70" fill="none" stroke="var(--sp-accent,#d4a72c)" stroke-width="4" stroke-linecap="round"/>
<g fill="var(--sp-primary,#0b1f3a)" stroke="#fff" stroke-width="2"><circle cx="200" cy="226" r="7"/><circle cx="360" cy="160" r="7"/><circle cx="620" cy="70" r="7"/></g>
<text x="40" y="285" font-size="12" fill="currentColor" fill-opacity=".7">Start</text><text x="620" y="285" text-anchor="end" font-size="12" fill="currentColor" fill-opacity=".7">Month 12</text>
</svg>
<figcaption>Typical shape of an SEO project (illustration, not a promise). Real timing depends on your site, market and competition.</figcaption>
</figure>`);

// ---------- Service page builder ----------
const service = (s) => [
	hero(s.eyebrow, s.h1, s.lead, [['Get a free SEO review', '/get-a-quote/'], ['See pricing', '/pricing/', true]], s.points),
	section({}, [p('What is included', 'semrs-eyebrow'), h(s.includedTitle), s.includedText ? p(esc(s.includedText)) : '', grid(3, s.included.map(([i, t, x]) => card(i, t, x)))]),
	section({ layout: 'row', valign: 'center', gap: 48, bg: 'var(--sp-surface)' }, [group([p('Who it is for', 'semrs-eyebrow'), h(s.forTitle), p(esc(s.forText)), checks(s.forPoints)]), group([p('Our promise', 'semrs-eyebrow'), h('What we control, and what we never claim', 3), checks(['A written plan you approve before work starts', 'A person reviews every deliverable before it goes live', 'Reports from your own Google Search Console and GA4 data', 'Month-to-month plans with 30 days’ notice', 'No ranking or traffic guarantees: nobody can honestly promise them'])])]),
	steps(s.stepsTitle, s.steps),
	s.tools ? tools(s.tools) : '',
	faq(s.faq),
	cta(s.ctaTitle, s.ctaText),
].filter(Boolean).join('\n\n');

